DO $autonomy_verify$
DECLARE expected record;actual jsonb;role_name text;privilege_name text;allowed text[];fn jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM forge_agent.schema_migrations WHERE version=16 AND name='coding_autonomous_workflows') THEN RAISE EXCEPTION 'Missing M16 feedback migration';END IF;
 FOR expected IN SELECT 'coding_workflows'::text AS name,$catalog0${"acl":["forge_agent_owner=arwdDxt/forge_agent_owner","forge_agent=arw/forge_agent_owner"],"columns":[["workflow_id","uuid",true,"gen_random_uuid()"],["owner_id","text",true,null],["project_alias","text",true,null],["root_task_id","uuid",true,null],["policy_digest","text",true,null],["snapshot","jsonb",true,null],["phase","text",true,"'plan'::text"],["plan_revisions","integer",true,"0"],["escalation_reason","text",true,"''::text"],["enabled","boolean",true,"true"],["created_at","timestamp with time zone",true,"clock_timestamp()"],["updated_at","timestamp with time zone",true,"clock_timestamp()"]],"indexes":[["coding_workflows_owner_id_project_alias_root_task_id_key","CREATE UNIQUE INDEX coding_workflows_owner_id_project_alias_root_task_id_key ON forge_agent.coding_workflows USING btree (owner_id, project_alias, root_task_id)",true,true],["coding_workflows_owner_id_project_alias_workflow_id_key","CREATE UNIQUE INDEX coding_workflows_owner_id_project_alias_workflow_id_key ON forge_agent.coding_workflows USING btree (owner_id, project_alias, workflow_id)",true,true],["coding_workflows_pkey","CREATE UNIQUE INDEX coding_workflows_pkey ON forge_agent.coding_workflows USING btree (workflow_id)",true,true]],"triggers":[["coding_workflows_evidence_guard","CREATE TRIGGER coding_workflows_evidence_guard BEFORE UPDATE ON forge_agent.coding_workflows FOR EACH ROW EXECUTE FUNCTION forge_agent.coding_workflow_evidence_guard()","O"]],"constraints":[["coding_workflows_escalation_reason_check","c","CHECK ((octet_length(escalation_reason) <= 4096))",true,false,false],["coding_workflows_owner_id_project_alias_root_task_id_fkey","f","FOREIGN KEY (owner_id, project_alias, root_task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)",true,false,false],["coding_workflows_owner_id_project_alias_root_task_id_key","u","UNIQUE (owner_id, project_alias, root_task_id)",true,false,false],["coding_workflows_owner_id_project_alias_workflow_id_key","u","UNIQUE (owner_id, project_alias, workflow_id)",true,false,false],["coding_workflows_phase_check","c","CHECK ((phase = ANY (ARRAY['plan'::text, 'plan_review'::text, 'plan_revision'::text, 'implement'::text, 'checks'::text, 'code_review'::text, 'repair'::text, 'publishing'::text, 'hosted'::text, 'merging'::text, 'completed'::text, 'cancelled'::text, 'escalated'::text])))",true,false,false],["coding_workflows_pkey","p","PRIMARY KEY (workflow_id)",true,false,false],["coding_workflows_plan_revisions_check","c","CHECK (((plan_revisions >= 0) AND (plan_revisions <= 3)))",true,false,false],["coding_workflows_policy_digest_check","c","CHECK ((policy_digest ~ '^[0-9a-f]{64}$'::text))",true,false,false],["coding_workflows_snapshot_check","c","CHECK ((jsonb_typeof(snapshot) = 'object'::text))",true,false,false]]}$catalog0$::jsonb AS data LOOP
SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),'acl',to_jsonb(c.relacl),'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) INTO actual FROM pg_class c WHERE c.oid=('forge_agent.'||expected.name)::regclass AND c.relowner='forge_agent_owner'::regrole;
 IF actual IS DISTINCT FROM expected.data THEN RAISE EXCEPTION 'Autonomy schema drift: %',expected.name;END IF;
 END LOOP;
