s_check","c","CHECK ((((target_json IS NULL) AND (target_sha256 IS NULL)) OR ((target_json IS NOT NULL) AND (target_sha256 = encode(sha256(convert_to(target_json, 'UTF8'::name)), 'hex'::text)))))",true,false,false],["coding_workflow_reviews_check1","c","CHECK ((((verdict_json IS NULL) AND (verdict_sha256 IS NULL)) OR ((verdict_json IS NOT NULL) AND (verdict_sha256 = encode(sha256(convert_to(verdict_json, 'UTF8'::name)), 'hex'::text)))))",true,false,false],["coding_workflow_reviews_gate_manifest_sha256_check","c","CHECK (((gate_manifest_sha256 IS NULL) OR (gate_manifest_sha256 ~ '^[0-9a-f]{64}$'::text)))",true,false,false],["coding_workflow_reviews_owner_id_project_alias_reviewer_ta_fkey","f","FOREIGN KEY (owner_id, project_alias, reviewer_task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)",true,false,false],["coding_workflow_reviews_owner_id_project_alias_source_task_fkey","f","FOREIGN KEY (owner_id, project_alias, source_task_id, source_attempt_id) REFERENCES forge_agent.coding_attempts(owner_id, project_alias, task_id, attempt_id)",true,false,false],["coding_workflow_reviews_pkey","p","PRIMARY KEY (workflow_review_id)",true,false,false],["coding_workflow_reviews_reviewer_result_sha256_check","c","CHECK (((reviewer_result_sha256 IS NULL) OR (reviewer_result_sha256 ~ '^[0-9a-f]{64}$'::text)))",true,false,false],["coding_workflow_reviews_source_result_sha256_check","c","CHECK ((source_result_sha256 ~ '^[0-9a-f]{64}$'::text))",true,false,false],["coding_workflow_reviews_source_review_id_fkey","f","FOREIGN KEY (source_review_id) REFERENCES forge_agent.coding_reviews(review_id)",true,false,false],["coding_workflow_reviews_source_revision_check","c","CHECK ((source_revision > 0))",true,false,false],["coding_workflow_reviews_status_check","c","CHECK ((status = ANY (ARRAY['pending'::text, 'reviewing'::text, 'decided'::text, 'escalated'::text, 'cancelled'::text])))",true,false,false],["coding_workflow_reviews_target_json_check","c","CHECK (((target_json IS NULL) OR (octet_length(target_json) <= 67174400)))",true,false,false],["coding_workflow_reviews_target_kind_check","c","CHECK ((target_kind = ANY (ARRAY['plan'::text, 'code'::text])))",true,false,false],["coding_workflow_reviews_target_sha256_check","c","CHECK (((target_sha256 IS NULL) OR (target_sha256 ~ '^[0-9a-f]{64}$'::text)))",true,false,false],["coding_workflow_reviews_verdict_json_check","c","CHECK (((verdict_json IS NULL) OR (octet_length(verdict_json) <= 65536)))",true,false,false],["coding_workflow_reviews_verdict_sha256_check","c","CHECK (((verdict_sha256 IS NULL) OR (verdict_sha256 ~ '^[0-9a-f]{64}$'::text)))",true,false,false],["coding_workflow_reviews_workflow_id_fkey","f","FOREIGN KEY (workflow_id) REFERENCES forge_agent.coding_workflows(workflow_id)",true,false,false],["coding_workflow_reviews_workflow_id_target_kind_source_atte_key","u","UNIQUE NULLS NOT DISTINCT (workflow_id, target_kind, source_attempt_id, source_review_id)",true,false,false]]}$catalog1$::jsonb AS data LOOP
