 IF actual IS DISTINCT FROM expected.data THEN RAISE EXCEPTION 'Autonomy schema drift: %',expected.name;END IF;
 END LOOP;
 FOR expected IN SELECT 'coding_workflow_actions'::text AS name,$catalog2${"acl":["forge_agent_owner=arwdDxt/forge_agent_owner","forge_agent=arw/forge_agent_owner"],"columns":[["action_id","uuid",true,"gen_random_uuid()"],["workflow_id","uuid",true,null],["owner_id","text",true,null],["project_alias","text",true,null],["workflow_review_id","uuid",false,null],["kind","text",true,null],["source_key","text",true,null],["source_publication_id","uuid",false,null],["status","text",true,"'pending'::text"],["worker_id","text",false,null],["lease_token","uuid",false,null],["lease_expires_at","timestamp with time zone",false,null],["intent","jsonb",false,null],["finish_receipt","jsonb",false,null],["finish_token","uuid",false,null],["created_at","timestamp with time zone",true,"clock_timestamp()"],["updated_at","timestamp with time zone",true,"clock_timestamp()"]],"indexes":[["coding_workflow_actions_pending","CREATE INDEX coding_workflow_actions_pending ON forge_agent.coding_workflow_actions USING btree (owner_id, kind, status, created_at)",true,true],["coding_workflow_actions_pkey","CREATE UNIQUE INDEX coding_workflow_actions_pkey ON forge_agent.coding_workflow_actions USING btree (action_id)",true,true],["coding_workflow_actions_workflow_id_kind_source_key_key","CREATE UNIQUE INDEX coding_workflow_actions_workflow_id_kind_source_key_key ON forge_agent.coding_workflow_actions USING btree (workflow_id, kind, source_key)",true,true]],"triggers":[["coding_workflow_actions_evidence_guard","CREATE TRIGGER coding_workflow_actions_evidence_guard BEFORE UPDATE ON forge_agent.coding_workflow_actions FOR EACH ROW EXECUTE FUNCTION forge_agent.coding_workflow_evidence_guard()","O"]],"constraints":[["coding_workflow_actions_check","c","CHECK ((((lease_token IS NULL) AND (lease_expires_at IS NULL)) OR ((lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL))))",true,false,false],["coding_workflow_actions_intent_check","c","CHECK (((intent IS NULL) OR (octet_length((intent)::text) <= 65536)))",true,false,false],["coding_workflow_actions_kind_check","c","CHECK ((kind = ANY (ARRAY['review'::text, 'decide'::text, 'merge'::text])))",true,false,false],["coding_workflow_actions_pkey","p","PRIMARY KEY (action_id)",true,false,false],["coding_workflow_actions_source_key_check","c","CHECK (((octet_length(source_key) >= 1) AND (octet_length(source_key) <= 256)))",true,false,false],["coding_workflow_actions_source_publication_id_fkey","f","FOREIGN KEY (source_publication_id) REFERENCES forge_agent.coding_publications(publication_id)",true,false,false],["coding_workflow_actions_status_check","c","CHECK ((status = ANY (ARRAY['pending'::text, 'leased'::text, 'completed'::text, 'handoff'::text, 'needs_reconcile'::text, 'cancelled'::text])))",true,false,false],["coding_workflow_actions_workflow_id_fkey","f","FOREIGN KEY (workflow_id) REFERENCES forge_agent.coding_workflows(workflow_id)",true,false,false],["coding_workflow_actions_workflow_id_kind_source_key_key","u","UNIQUE (workflow_id, kind, source_key)",true,false,false],["coding_workflow_actions_workflow_review_id_fkey","f","FOREIGN KEY (workflow_review_id) REFERENCES forge_agent.coding_workflow_reviews(workflow_review_id)",true,false,false]]}$catalog2$::jsonb AS data LOOP
SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),'acl',to_jsonb(c.relacl),'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) INTO actual FROM pg_class c WHERE c.oid=('forge_agent.'||expected.name)::regclass AND c.relowner='forge_agent_owner'::regrole;
 IF actual IS DISTINCT FROM expected.data THEN RAISE EXCEPTION 'Autonomy schema drift: %',expected.name;END IF;
 END LOOP;
 SELECT jsonb_build_array(p.prosrc,p.prosecdef,p.proconfig,p.provolatile,p.proacl) INTO actual FROM pg_proc p WHERE p.oid='forge_agent.coding_workflow_evidence_guard()'::regprocedure AND p.proowner='forge_agent_owner'::regrole;
 IF actual IS DISTINCT FROM $function0$["\nBEGIN\n IF TG_TABLE_NAME='coding_workflows' THEN\n IF (NEW.owner_id,NEW.project_alias,NEW.root_task_id,NEW.policy_digest,NEW.snapshot) IS DISTINCT FROM(OLD.owner_id,OLD.project_alias,OLD.root_task_id,OLD.policy_digest,OLD.snapshot) THEN RAISE EXCEPTION 'Immutable workflow authority' USING ERRCODE='P0009';END IF;END IF;\n IF TG_TABLE_NAME='coding_workflow_reviews' THEN\n  IF (NEW.workflow_id,NEW.owner_id,NEW.project_alias,NEW.target_kind,NEW.source_task_id,NEW.source_attempt_id,NEW.source_result_sha256,NEW.source_revision,NEW.source_review_id,NEW.candidate_commit,NEW.gate_manifest_sha256) IS DISTINCT FROM(OLD.workflow_id,OLD.owner_id,OLD.project_alias,OLD.target_kind,OLD.source_task_id,OLD.source_attempt_id,OLD.source_result_sha256,OLD.source_revision,OLD.source_review_id,OLD.candidate_commit,OLD.gate_manifest_sha256)\n   OR(OLD.target_json IS NOT NULL AND(NEW.target_json,NEW.target_sha256,NEW.reviewer_task_id) IS DISTINCT FROM(OLD.target_json,OLD.target_sha256,OLD.reviewer_task_id))\n   OR(OLD.verdict_json IS NOT NULL AND(NEW.verdict_json,NEW.verdict_sha256,NEW.reviewer_attempt_id,NEW.reviewer_result_sha256) IS DISTINCT FROM(OLD.verdict_json,OLD.verdict_sha256,OLD.reviewer_attempt_id,OLD.reviewer_result_sha256)) THEN RAISE EXCEPTION 'Immutable peer review evidence' USING ERRCODE='P0009';END IF;\n END IF;\n IF TG_TABLE_NAME='coding_workflow_actions' THEN\n IF (OLD.intent IS NOT NULL AND NEW.intent IS DISTINCT FROM OLD.intent OR OLD.finish_receipt IS NOT NULL AND NEW.finish_receipt IS DISTINCT FROM OLD.finish_receipt) THEN RAISE EXCEPTION 'Immutable workflow receipt' USING ERRCODE='P0009';END IF;END IF;\n RETURN NEW;\nEND;",false,["search_path=pg_catalog, pg_temp"],"v",["forge_agent_owner=X/forge_agent_owner"]]$function0$::jsonb THEN RAISE EXCEPTION 'Autonomy function drift: forge_agent.coding_workflow_evidence_guard()';END IF;
 SELECT jsonb_build_array(p.prosrc,p.prosecdef,p.proconfig,p.provolatile,p.proacl) INTO actual FROM pg_proc p WHERE p.oid='forge_agent.coding_workflow_attempt_context()'::regprocedure AND p.proowner='forge_agent_owner'::regrole;
 IF actual IS DISTINCT FROM $function1$["\nBEGIN\n SELECT workflow_id,workflow_review_id,review_target_sha256,workflow_feedback_review_id,workflow_feedback_sha256\n INTO NEW.workflow_id,NEW.workflow_review_id,NEW.review_target_sha256,NEW.workflow_feedback_review_id,NEW.workflow_feedback_sha256\n FROM forge_agent.coding_tasks WHERE(owner_id,project_alias,id)=(NEW.owner_id,NEW.project_alias,NEW.task_id);\n RETURN NEW;\nEND;",true,["search_path=pg_catalog, pg_temp"],"v",["forge_agent_owner=X/forge_agent_owner"]]$function1$::jsonb THEN RAISE EXCEPTION 'Autonomy function drift: forge_agent.coding_workflow_attempt_context()';END IF;
 SELECT jsonb_build_array(p.prosrc,p.prosecdef,p.proconfig,p.provolatile,p.proacl) INTO actual FROM pg_proc p WHERE p.oid='forge_coding_worker_api.read_review_target(uuid,uuid)'::regprocedure AND p.proowner='forge_agent_owner'::regrole;
 IF actual IS DISTINCT FROM $function2$["\nDECLARE a forge_agent.coding_attempts%ROWTYPE;r forge_agent.coding_workflow_reviews%ROWTYPE;\nBEGIN\n a:=forge_coding_worker_api._lock_task_and_attempt(p_attempt,p_token);\n IF a.attempt_id IS NULL OR a.lease_expires_at IS NULL OR a.lease_expires_at<=clock_timestamp() OR a.deadline_at<=clock_timestamp() OR a.pinned_recipe->>'mode'<>'review' THEN RAISE EXCEPTION 'Invalid reviewer attempt' USING ERRCODE='42501';END IF;\n IF a.workflow_review_id IS NULL THEN RETURN NULL;END IF;\n SELECT * INTO r FROM forge_agent.coding_workflow_reviews WHERE workflow_review_id=a.workflow_review_id AND workflow_id=a.workflow_id AND owner_id=a.owner_id AND project_alias=a.project_alias AND reviewer_task_id=a.task_id;\n IF NOT FOUND OR r.target_sha256 IS DISTINCT FROM a.review_target_sha256 OR r.target_json IS NULL OR r.status<>'reviewing' OR NOT EXISTS(SELECT 1 FROM forge_agent.coding_workflows w JOIN forge_agent.coding_tasks t ON t.workflow_id=w.workflow_id WHERE w.workflow_id=a.workflow_id AND w.enabled AND w.phase NOT IN('cancelled','escalated','completed') AND t.id=a.task_id AND t.status='running' AND t.latest_attempt_id=a.attempt_id) THEN RAISE EXCEPTION 'Review target no longer authorized' USING ERRCODE='P0009';END IF;\n RETURN jsonb_build_object('target_json',r.target_json,'target_sha256',r.target_sha256);\nEND;",true,["search_path=pg_catalog, pg_temp"],"v",["forge_agent_owner=X/forge_agent_owner","forge_coding_worker=X/forge_agent_owner"]]$function2$::jsonb THEN RAISE EXCEPTION 'Autonomy function drift: forge_coding_worker_api.read_review_target(uuid,uuid)';END IF;
 SELECT jsonb_build_array(p.prosrc,p.prosecdef,p.proconfig,p.provolatile,p.proacl) INTO actual FROM pg_proc p WHERE p.oid='forge_coding_worker_api.claim(text,uuid,text[])'::regprocedure AND p.proowner='forge_agent_owner'::regrole;
 IF actual IS DISTINCT FROM $function3$["\nDECLARE\n    v_candidate record;\n    v_task forge_agent.coding_tasks%ROWTYPE;\n    v_attempt_id uuid;\n    v_attempt_token uuid;\n    v_attempt_no integer;\n    v_unit_name text;\n    v_now timestamptz;\n    v_lease_expires timestamptz;\n    v_deadline timestamptz;\n    v_resume_digest text;\n    v_new_revision bigint;\nBEGIN\n    IF p_worker_id IS NULL OR p_worker_id !~ '^[A-Za-z0-9_.-]{1,64}$'\n       OR p_incarnation IS NULL\n       OR p_allowed_profiles IS NULL\n       OR pg_catalog.array_length(p_allowed_profiles, 1) IS NULL\n       OR pg_catalog.array_length(p_allowed_profiles, 1) > 64 THEN\n        RAISE EXCEPTION 'Invalid coding worker claim parameters' USING ERRCODE = '22023';\n    END IF;\n\n    IF NOT EXISTS (\n        SELECT 1 FROM forge_agent.coding_worker_grants g\n        WHERE g.worker_role = session_user\n          AND g.owner_id = pg_catalog.current_setting('forge.coding_owner', true)\n    ) THEN\n        RAISE EXCEPTION 'Coding worker role has no grant for configured owner' USING ERRCODE = '42501';\n    END IF;\n\n    FOR v_candidate IN\n        SELECT t.owner_id, t.project_alias, t.id\n        FROM forge_agent.coding_tasks t\n        JOIN forge_agent.coding_worker_readiness r\n          ON r.worker_role = session_user\n         AND r.owner_id = t.owner_id\n         AND r.worker_id = p_worker_id\n         AND r.incarnation = p_incarnation\n         AND r.observed_at > clock_timestamp() - interval '90 seconds'\n        JOIN forge_agent.coding_worker_grants g\n          ON g.worker_role = session_user\n              AND g.owner_id = pg_catalog.current_setting('forge.coding_owner', true)\n         AND g.owner_id = t.owner_id\n         AND g.project_alias = t.project_alias\n         AND g.agent_profile = t.agent_profile\n         AND g.mode = t.mode\n        WHERE t.status = 'queued'\n          AND(t.workflow_id IS NULL OR EXISTS(SELECT 1 FROM forge_agent.coding_workflows w WHERE w.workflow_id=t.workflow_id AND w.enabled AND w.phase NOT IN('completed','cancelled','escalated')))\n          AND t.owner_id = pg_catalog.current_setting('forge.coding_owner', true)\n          AND t.agent_profile = ANY(p_allowed_profiles)\n          AND (t.pinned_recipe->'version') = '2'::jsonb\n          AND (t.pinned_recipe->>'resource_profile') IN ('forge-coding-v1', 'forge-coding-v2', 'forge-coding-v3', 'forge-coding-v4', 'forge-coding-v5', 'forge-coding-v6', 'forge-coding-v7', 'forge-coding-v8', 'forge-coding-v9', 'forge-coding-v10')\n          AND (t.pinned_recipe->>'policy_digest') = r.policy_digest\n          AND (t.pinned_recipe->>'backend'<>'muse' OR EXISTS (\n              SELECT 1 FROM jsonb_array_elements(r.profiles) AS configured(profile)\n              WHERE profile->>'alias'=t.agent_profile\n                AND profile->>'backend'='muse'\n                AND profile->>'model'=t.pinned_recipe->>'model'\n                AND profile->'modes' ? t.mode\n          ))\n          AND (t.pinned_recipe->>'backend'<>'grok' OR EXISTS (\n              SELECT 1 FROM jsonb_array_elements(r.profiles) AS configured(profile)\n              WHERE profile->>'alias'=t.agent_profile\n                AND profile->>'backend'='grok'\n                AND profile->>'model'=t.pinned_recipe->>'model'\n                AND profile->'modes' ? t.mode\n          ))\n          AND NOT EXISTS (\n              SELECT 1\n              FROM forge_agent.coding_attempts a\n              WHERE a.owner_id = t.owner_id\n                AND a.project_alias = t.project_alias\n                AND a.task_id = t.id\n                AND (a.reservation_active OR a.lease_expires_at IS NOT NULL)\n          )\n        ORDER BY t.created_at ASC, t.id ASC\n    LOOP\n        SELECT t.*\n        INTO v_task\n        FROM forge_agent.coding_tasks t\n        WHERE t.owner_id = v_candidate.owner_id\n          AND t.project_alias = v_candidate.project_alias\n          AND t.id = v_candidate.id\n          AND t.status = 'queued'\n          AND(t.workflow_id IS NULL OR EXISTS(SELECT 1 FROM forge_agent.coding_workflows w WHERE w.workflow_id=t.workflow_id AND w.enabled AND w.phase NOT IN('completed','cancelled','escalated')))\n        FOR UPDATE SKIP LOCKED;\n        IF NOT FOUND THEN\n            CONTINUE;\n        END IF;\n\n        IF EXISTS (\n            SELECT 1\n            FROM forge_agent.coding_attempts a\n            WHERE a.owner_id = v_task.owner_id\n              AND a.project_alias = v_task.project_alias\n              AND a.task_id = v_task.id\n              AND (a.reservation_active OR a.lease_expires_at IS NOT NULL)\n        ) THEN\n            CONTINUE;\n        END IF;\n\n        IF v_task.revision >= 9007199254740991 THEN\n            CONTINUE;\n        END IF;\n\n        v_now := clock_timestamp();\n        v_lease_expires := v_now + interval '60 seconds';\n        v_deadline := v_now + interval '1800 seconds';\n        v_attempt_id := pg_catalog.gen_random_uuid();\n        v_attempt_token := pg_catalog.gen_random_uuid();\n        v_unit_name := 'forge-coding-' || pg_catalog.replace(v_attempt_id::text, '-', '');\n        v_resume_digest := v_task.resume_workspace_digest;\n\n        SELECT coalesce(max(a.attempt_no), 0) + 1\n        INTO v_attempt_no\n        FROM forge_agent.coding_attempts a\n        WHERE a.owner_id = v_task.owner_id\n          AND a.project_alias = v_task.project_alias\n          AND a.task_id = v_task.id;\n\n        INSERT INTO forge_agent.coding_attempts (\n            owner_id, project_alias, task_id, attempt_id, attempt_no,\n            attempt_token, agent_profile, pinned_recipe, recipe_digest,\n            worker_role, worker_id, worker_incarnation,\n            unit_name, phase, reservation_active, resume_workspace_digest, plan_decision_id,\n            lease_expires_at, deadline_at, started_at, updated_at,feedback_id,feedback_sha256,legacy_resume_note,repair_source_review_id,repair_candidate_commit,scope_plan_decision_id\n        )\n        VALUES (\n  